namespace ghidra.app.plugin.core.debug.service.breakpoint;



using db;
using ghidra.async;
using ghidra.trace.model.breakpoint;

public record DeleteEmuBreakpointActionItem(TraceBreakpointLocation loc, long snap) : BreakpointActionItem {
	/* @Override */
	public CompletableFuture<Void> execute() {
		using (Transaction tx =
			loc.getTrace().openTransaction("Delete Emulated Breakpoint"))
{
			string emuName = PlaceEmuBreakpointActionItem.createName(loc.getMinAddress(snap));
			if (loc.getPath().contains(emuName)) {
				loc.delete();
			}
			else {
				loc.setEmuEnabled(snap, false);
			}
		}
		return AsyncUtils.nil();
	}
}
